function setText(el,text){if(el)el.textContent=text}function esc(s=''){return String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}function toast(s){$('toast').textContent=s;$('toast').classList.add('show');setTimeout(()=>$('toast').classList.remove('show'),3200)}function status(id,msg,type=''){const e=$(id);e.textContent=msg;e.className='status '+type}
