async function loadI18n(){try{const [fa,en]=await Promise.all([fetch('/static/shared/i18n/fa.json').then(r=>r.json()),fetch('/static/shared/i18n/en.json').then(r=>r.json())]);tr={fa:Object.assign({},tr.fa,fa),en:Object.assign({},tr.en,en)}}catch(e){}}
function applyLanguage(){document.documentElement.lang=lang;document.documentElement.dir=lang==='fa'?'rtl':'ltr';document.querySelectorAll('[data-i18n]').forEach(e=>{const key=e.dataset.i18n;if(tr[lang][key])e.textContent=tr[lang][key]});document.querySelectorAll('[data-i18n-aria]').forEach(e=>{const key=e.dataset.i18nAria;if(tr[lang][key])e.setAttribute('aria-label',tr[lang][key])});document.querySelectorAll('[data-i18n-placeholder]').forEach(e=>{const key=e.dataset.i18nPlaceholder;if(tr[lang][key])e.setAttribute('placeholder',tr[lang][key])});$('langBtn').textContent=lang==='fa'?'English':'فارسی';updateToday();updateScientificGuide(document.querySelector('.nav.active')?.dataset.tab||'overview');if(lastPower){renderAnalysis(lastPower);renderPowerSummary(lastPower)}if(lastFao){renderFao(lastFao,$('faoMetric').value);renderFaoSummary(lastFao,$('faoMetric').value)}if(lastFaoWorld)renderFaoWorld(lastFaoWorld);if(lastClimate)renderClimate(lastClimate);if(lastAdvice)renderAdvice(lastAdvice)}$('langBtn').addEventListener('click',()=>{lang=lang==='fa'?'en':'fa';applyLanguage();loadFaq()});
