function updateScientificGuide(tab){const el=$('scientificGuide');if(!el)return;const item=scientificGuides[tab]||scientificGuides.overview;const g=item[lang]||item.fa;el.querySelector('strong').textContent=g[0];el.querySelector('span').textContent=g[1];el.setAttribute('aria-label',lang==='fa'?'راهنمای محیط علمی':'Scientific workspace guide');}
document.querySelectorAll('.nav').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.tab)));document.querySelectorAll('[data-go]').forEach(b=>b.addEventListener('click',()=>showTab(b.dataset.go)));function showTab(tab){document.querySelectorAll('.nav').forEach(b=>b.classList.toggle('active',b.dataset.tab===tab));document.querySelectorAll('.tab-panel').forEach(p=>p.classList.toggle('hidden',p.id!==`tab-${tab}`));updateScientificGuide(tab);if(tab==='power')loadParameters();if(tab==='faq')loadFaq();if(tab==='fao'&&!lastFao)loadFao(false);if(tab==='advisor'&&!$('advCrop').options.length)loadAdvCrops();if(tab==='climate'){$('climLat').value=$('lat').value;$('climLon').value=$('lon').value}if(tab==='workspace'&&typeof loadAnalyses==='function')loadAnalyses();if(tab==='overview'){initSatMap();if(satMap)setTimeout(()=>satMap.invalidateSize(),60)}}

let coordLabel,crossH,crossV;
function initMap(){const svg=$('coordMap');if(!svg)return;const NS='http://www.w3.org/2000/svg';const el=(t,a)=>{const e=document.createElementNS(NS,t);for(const k in a)e.setAttribute(k,a[k]);return e};svg.append(el('rect',{x:0,y:0,width:360,height:180,fill:'#dcebf5'}));for(let lon=-150;lon<=150;lon+=30)svg.append(el('line',{x1:lon+180,y1:0,x2:lon+180,y2:180,stroke:'#b9d2e4','stroke-width':lon===0?1.4:.6}));for(let lat=-60;lat<=60;lat+=30)svg.append(el('line',{x1:0,y1:90-lat,x2:360,y2:90-lat,stroke:'#b9d2e4','stroke-width':lat===0?1.4:.6}));svg.append(el('line',{x1:0,y1:90,x2:360,y2:90,stroke:'#9db8cc','stroke-width':1}));svg.append(el('line',{x1:180,y1:0,x2:180,y2:180,stroke:'#9db8cc','stroke-width':1}));crossH=el('line',{y1:0,y2:180,stroke:'#d64545','stroke-width':.8,'stroke-dasharray':'3 3',opacity:.55});crossV=el('line',{x1:0,x2:360,stroke:'#d64545','stroke-width':.8,'stroke-dasharray':'3 3',opacity:.55});svg.append(crossH,crossV);marker=el('circle',{r:5,fill:'#d64545',stroke:'#fff','stroke-width':1.6});svg.append(marker);coordLabel=el('text',{fill:'#10243a','font-size':9,'font-weight':700,'text-anchor':'middle',style:'paint-order:stroke',stroke:'#fff','stroke-width':3});svg.append(coordLabel);svg.addEventListener('click',e=>{const r=svg.getBoundingClientRect();const lon=(e.clientX-r.left)/r.width*360-180,lat=90-(e.clientY-r.top)/r.height*180;setCoords(lat,lon)});setCoords(32.0853,34.7818)}
function setCoords(lat,lon){lat=Math.max(-90,Math.min(90,lat));lon=Math.max(-180,Math.min(180,lon));$('lat').value=Number(lat).toFixed(4);$('lon').value=Number(lon).toFixed(4);const x=lon+180,y=90-lat;if(marker){marker.setAttribute('cx',x);marker.setAttribute('cy',y)}if(coordLabel){coordLabel.setAttribute('x',Math.min(350,Math.max(10,x)));coordLabel.setAttribute('y',Math.max(12,Math.min(175,y-8)));coordLabel.textContent=`${Number(lat).toFixed(2)}°, ${Number(lon).toFixed(2)}°`}if(crossH){crossH.setAttribute('x1',x);crossH.setAttribute('x2',x);crossV.setAttribute('y1',y);crossV.setAttribute('y2',y)}}
async function searchGeo(){const q=$('geoQuery').value.trim();const box=$('geoResults');if(q.length<3){box.innerHTML='';return}box.innerHTML=skeletonCards(2);try{const r=await fetch(`/api/geocode/?q=${encodeURIComponent(q)}`),d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);if(!d.items.length){box.innerHTML=emptyState('📍',lang==='fa'?'مکانی با این نام پیدا نشد — نام را دقیق‌تر بنویسید یا مختصات را دستی وارد کنید':'No place found with this name — try a more precise name or enter coordinates manually');return}box.innerHTML=d.items.map((it,i)=>`<button class="geo-result" data-i="${i}"><b>${esc(it.display_name.split(',').slice(0,3).join('، '))}</b><span>${it.lat.toFixed(4)} ، ${it.lon.toFixed(4)}</span></button>`).join('');box.querySelectorAll('.geo-result').forEach(b=>b.addEventListener('click',()=>{const it=d.items[Number(b.dataset.i)];setCoords(it.lat,it.lon);$('geoResults').innerHTML='';$('geoQuery').value=it.display_name.split(',')[0];toast(lang==='fa'?'موقعیت انتخاب شد':'Location selected')}))}catch(e){box.innerHTML=emptyState('⚠️',e.message)}}
$('geoSearch').addEventListener('click',searchGeo);$('geoQuery').addEventListener('keydown',e=>{if(e.key==='Enter')searchGeo()});
function compactDate(v){return v.replaceAll('-','')}async function loadPower(){const params=[...document.querySelectorAll('.checks input:checked')].map(x=>x.value);if(!params.length){status('powerStatus',lang==='fa'?'حداقل یک پارامتر انتخاب کنید':'Select at least one parameter','error');return}const la=Number($('lat').value),lo=Number($('lon').value);if(!Number.isFinite(la)||!Number.isFinite(lo)||la<-90||la>90||lo<-180||lo>180){status('powerStatus',lang==='fa'?'مختصات نامعتبر است':'Invalid coordinates','error');return}const q=new URLSearchParams({lat:$('lat').value,lon:$('lon').value,start:compactDate($('start').value),end:compactDate($('end').value),community:$('community').value,temporal:$('temporal').value});params.forEach(p=>q.append('parameter',p));status('powerStatus',lang==='fa'?'در حال دریافت داده از NASA POWER…':'Requesting NASA POWER…');$('loadPower').disabled=true;$('analysis').innerHTML=skeletonCards(4);overlaySkeleton('powerChart');try{const r=await fetch(`/api/power/?${q}`),data=await r.json();if(!r.ok)throw Error(data.error||r.statusText);lastPower=data;renderPower(data);status('powerStatus',`${lang==='fa'?'دریافت شد':'Received'} · ${data.dates.length} ${lang==='fa'?'روز':'days'} · ${data.parameters.length} ${lang==='fa'?'پارامتر':'parameters'}`,'success');$('exportCsv').disabled=false}catch(e){clearSkeletons();status('powerStatus',e.message,'error')}finally{$('loadPower').disabled=false}}$('loadPower').addEventListener('click',loadPower);
function renderPower(data){clearSkeletons();const ce=$('chartEmpty');if(ce)ce.style.display='none';if(chart)chart.destroy();const colors=['#087f8c','#e7a33e','#4263a5','#c45b5b','#6c8d54','#8256a1'];const datasets=data.parameters.map((p,i)=>({label:`${p.code} (${p.unit})`,data:p.points.map(x=>x.value),borderColor:colors[i%colors.length],backgroundColor:colors[i%colors.length],borderWidth:2,pointRadius:0,tension:.22,yAxisID:`y${i}`}));const scales={x:{ticks:{maxTicksLimit:9,color:'#718096'},grid:{display:false}}};data.parameters.forEach((p,i)=>scales[`y${i}`]={type:'linear',display:true,position:i%2?'right':'left',title:{display:true,text:p.unit,color:colors[i%colors.length]},grid:{drawOnChartArea:i===0,color:document.documentElement.dataset.theme==='dark'?'#2a3a4c':'#edf1f4'},ticks:{color:colors[i%colors.length],maxTicksLimit:5},...(i>1?{display:false}:{})});chart=new Chart($('powerChart'),{type:'line',data:{labels:data.dates,datasets},options:{responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom',labels:{usePointStyle:true,boxWidth:7,font:{size:10}}},tooltip:{callbacks:{label:c=>`${c.dataset.label}: ${c.parsed.y??'—'}`}}},scales}});renderAnalysis(data);renderPowerSummary(data)}
function renderPowerSummary(data){const el=$('powerSummaryText');if(!el)return;const find=c=>data.parameters.find(p=>p.code===c);const vals=p=>p?p.points.map(x=>x.value).filter(v=>v!==null&&Number.isFinite(Number(v))).map(Number):[];const parts=[];const t=vals(find('T2M'));if(t.length)parts.push(`${L('میانگین دما','Mean temperature')} ${(t.reduce((a,b)=>a+b,0)/t.length).toFixed(1)}°C`);const r=vals(find('PRECTOTCORR'));if(r.length)parts.push(`${L('مجموع بارش','Total precipitation')} ${r.reduce((a,b)=>a+b,0).toFixed(1)} mm`);const h=vals(find('RH2M'));if(h.length)parts.push(`${L('میانگین رطوبت','Mean humidity')} ${Math.round(h.reduce((a,b)=>a+b,0)/h.length)}%`);const s=vals(find('ALLSKY_SFC_SW_DWN'));if(s.length)parts.push(`${L('میانگین تابش','Mean radiation')} ${(s.reduce((a,b)=>a+b,0)/s.length).toFixed(2)} kWh/m²`);if(!parts.length){el.style.display='none';return}el.style.display='block';el.innerHTML=`<small>${L('📋 خلاصه به زبان ساده','📋 Plain-language summary')}</small><b style="font-size:14px">${L('در '+data.dates.length+' روز گذشته:','Over the last '+data.dates.length+' days:')} ${parts.join(' · ')}</b><span>${L('برای تفسیر کشاورزی دقیق‌تر به تب «مشاور کشاورز» بروید.','For a more precise agricultural interpretation, open the Agri Advisor tab.')}</span>`}
function renderAnalysis(data){const root=$('analysis');root.innerHTML='';const pv=data.provenance;if(pv){const q=pv.quality_status||'valid';const qFa={valid:L('معتبر','Valid'),partial:L('ناقص','Partial'),stale:L('قدیمی','Stale'),invalid:L('نامعتبر','Invalid')}[q]||q;const badge=document.createElement('div');badge.className='provenance-badge q-'+q;badge.innerHTML='<b>'+L('منبع','Source')+': '+esc(pv.source||'—')+'</b> · '+esc(pv.dataset_id||'')+' · '+esc(pv.temporal_resolution||'')+' · '+L('کیفیت','Quality')+': '+esc(qFa)+' · '+L('دریافت','Retrieved')+': '+esc((pv.retrieved_at||'').slice(0,16).replace('T',' '));root.append(badge);}data.parameters.forEach(p=>{const vals=p.points.map(x=>x.value).filter(v=>v!==null&&Number.isFinite(Number(v))).map(Number);if(!vals.length)return;const avg=vals.reduce((a,b)=>a+b,0)/vals.length,min=Math.min(...vals),max=Math.max(...vals),first=vals[0],lastV=vals[vals.length-1],delta=first?((lastV-first)/Math.abs(first)*100):null;const div=document.createElement('div');div.className='analysis-card';div.innerHTML=`<small>${esc(lang==='en'?(p.name_en||p.name_fa):(p.name_fa||p.name_en))} · ${esc(p.code)}</small><b>${avg.toFixed(2)} ${esc(p.unit)}</b><span>min ${min.toFixed(2)} · max ${max.toFixed(2)} · n=${vals.length}${delta===null?'':` · ${delta>=0?'▲':'▼'} ${Math.abs(delta).toFixed(1)}%`}</span>`;root.append(div)})}
$('exportCsv').addEventListener('click',()=>{if(!lastPower)return;const dates=lastPower.dates;let rows=[['date',...lastPower.parameters.map(p=>`${p.code}_${p.unit}`)]];dates.forEach((d,i)=>rows.push([d,...lastPower.parameters.map(p=>{const x=p.points.find(x=>x.date===d);return x?.value??''})]));const csv='\ufeff'+rows.map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='nasa-power-timeseries.csv';a.click();URL.revokeObjectURL(a.href)});
async function loadParameters(){try{const r=await fetch('/api/power/parameters/'),d=await r.json();$('parameterList').innerHTML=d.parameters.map(p=>`<div class="parameter-item"><b>${esc(p.code)} · ${esc(p.unit)}</b><p>${esc(lang==='en'?(p.name_en||p.name_fa):p.name_fa)}${lang==='en'?` (${esc(p.name_fa)})`:''}</p></div>`).join('')}catch(e){$('parameterList').textContent=e.message}}
function isoDate(d){return d?`${d}T00:00:00Z`:''}async function searchCatalog(){catalogPage=1;catalogCursorStack=[];await fetchCatalog()}async function fetchCatalog(){const q=new URLSearchParams({q:$('catalogQuery').value,provider:$('provider').value,page_size:10});if(catalogCursorStack[catalogPage-1])q.set('cursor',catalogCursorStack[catalogPage-1]);if($('catStart').value)q.set('start',isoDate($('catStart').value));if($('catEnd').value)q.set('end',`${$('catEnd').value}T23:59:59Z`);status('catalogStatus',lang==='fa'?'در حال جست‌وجو در NASA CMR…':'Searching NASA CMR…');$('catalogResults').innerHTML='';$('catalogResults').innerHTML=skeletonCards(4);try{const r=await fetch(`/api/catalog/?${q}`),d=await r.json();if(!r.ok)throw Error(d.error);catalogHits=d.hits;if(d.next_cursor)catalogCursorStack[catalogPage]=d.next_cursor;status('catalogStatus',`${d.hits.toLocaleString()} ${lang==='fa'?'نتیجه':'results'} · ${lang==='fa'?'صفحه':'page'} ${d.page}`,'success');$('pageLabel').textContent=d.page;$('prevPage').disabled=catalogPage<=1;$('nextPage').disabled=!d.next_cursor;$('catalogResults').innerHTML=d.items.map((x,i)=>`<article class="catalog-card"><h4>${esc(x.title||x.short_name||'Untitled collection')}</h4><div class="catalog-meta"><span>${esc(x.short_name||'—')} · v${esc(x.version||'—')}</span><span>${esc(x.provider||'')}</span><span>${esc((x.platforms||[]).join(', '))}</span></div><p>${esc((x.abstract||'').slice(0,500))}${(x.abstract||'').length>500?'…':''}</p><div class="catalog-meta"><span>${esc(x.temporal?.[0]?.start||'')}</span><span>→ ${esc(x.temporal?.[0]?.end||'present')}</span><span>${esc(x.concept_id||'')}</span></div><div class="catalog-actions"><a target="_blank" rel="noopener" href="${esc(x.collection_url)}">Earthdata Search ↗</a><a target="_blank" rel="noopener" href="${esc(x.metadata_url)}">CMR Metadata ↗</a><button class="btn btn-ghost" data-granules="${esc(x.concept_id)}">${lang==='fa'?'نمایش گرانول‌ها':'Show granules'}</button></div><div id="granules-${i}" class="granule-box"></div></article>`).join('')||`<p>${lang==='fa'?'نتیجه‌ای پیدا نشد.':'No collections found.'}</p>`;document.querySelectorAll('[data-granules]').forEach(btn=>btn.addEventListener('click',()=>loadGranules(btn.dataset.granules,btn.closest('.catalog-card').querySelector('.granule-box'))))}catch(e){clearSkeletons();$('catalogResults').innerHTML=emptyState('🛰',lang==='fa'?'جست‌وجو ناموفق بود. دوباره تلاش کنید.':'Search failed. Please try again.');status('catalogStatus',e.message,'error')}}$('searchCatalog').addEventListener('click',searchCatalog);$('catalogQuery').addEventListener('keydown',e=>{if(e.key==='Enter')searchCatalog()});$('prevPage').addEventListener('click',()=>{catalogPage=Math.max(1,catalogPage-1);fetchCatalog()});$('nextPage').addEventListener('click',()=>{catalogPage++;fetchCatalog()});
async function loadGranules(id,root){root.innerHTML=`<div class="status">${lang==='fa'?'در حال دریافت گرانول‌ها…':'Loading granules…'}</div>`;const q=new URLSearchParams({concept_id:id,page_size:8});if($('catStart').value)q.set('start',isoDate($('catStart').value));if($('catEnd').value)q.set('end',`${$('catEnd').value}T23:59:59Z`);if($('bbox').value.trim())q.set('bbox',$('bbox').value.trim());try{const r=await fetch(`/api/granules/?${q}`),d=await r.json();if(!r.ok)throw Error(d.error);root.innerHTML=d.items.map(g=>`<div class="catalog-card"><b>${esc(g.title||g.producer_id||g.concept_id)}</b><div class="catalog-meta"><span>${esc(g.start||'')}</span><span>${g.size_mb?`${esc(g.size_mb)} bytes`:''}</span></div>${g.links.map(l=>`<div class="catalog-actions"><a target="_blank" rel="noopener" href="${esc(l.url)}">${lang==='fa'?'باز کردن منبع دانلود':'Open data link'} ↗</a><button class="btn btn-ghost" data-download="${esc(l.url)}">${lang==='fa'?'دانلود از سرور برنامه':'Download via app'}</button></div>`).join('')}</div>`).join('')||`<p>${lang==='fa'?'گرانول قابل دانلودی در این صفحه پیدا نشد.':'No downloadable granules found on this page.'}</p>`;root.querySelectorAll('[data-download]').forEach(b=>b.addEventListener('click',()=>downloadFile(b.dataset.download,b)))}catch(e){root.textContent=e.message}}
async function downloadFile(url,button){button.disabled=true;button.textContent=lang==='fa'?'در حال دانلود…':'Downloading…';try{const r=await fetch('/api/download/',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({url})}),d=await r.json();if(!r.ok)throw Error(d.error);const a=document.createElement('a');a.href=d.media_url;a.download=d.name;a.click();toast(`${lang==='fa'?'دریافت شد':'Downloaded'}: ${d.name} (${(d.bytes/1048576).toFixed(1)} MB)`);const inspect=document.createElement('button');inspect.className='btn btn-ghost';inspect.textContent=lang==='fa'?'بررسی ساختار فایل':'Inspect file';inspect.addEventListener('click',async()=>{inspect.disabled=true;try{const ir=await fetch(`/api/inspect/?file=${encodeURIComponent(d.name?d.path.split(/[\\/]/).pop(): '')}`);const idata=await ir.json();if(!ir.ok)throw Error(idata.error);let box=button.parentElement.querySelector('.inspect-output');if(!box){box=document.createElement('pre');box.className='inspect-output';button.parentElement.append(box)}box.textContent=JSON.stringify(idata,null,2)}catch(err){toast(err.message)}finally{inspect.disabled=false}});button.parentElement.append(inspect)}catch(e){toast(e.message)}finally{button.disabled=false;button.textContent=lang==='fa'?'دانلود از سرور برنامه':'Download via app'}}
async function loadFao(force=false){const crop=$('faoCrop').value,metric=$('faoMetric').value;status('faoStatus',lang==='fa'?'در حال دریافت داده از FAOSTAT…':'Fetching official FAOSTAT data…');$('loadFao').disabled=true;$('faoSummary').innerHTML='<div class="skeleton skeleton-chip"></div>'.repeat(4);$('faoTable').innerHTML=skeletonCards(3);overlaySkeleton('faoChart');try{const r=await fetch(`/api/fao/crops/${encodeURIComponent(crop)}/${force?'?refresh=1':''}`),d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);lastFao=d;renderFao(d,metric);renderFaoSummary(d,metric);status('faoStatus',`${lang==='fa'?'داده رسمی دریافت شد':'Official data received'} · ${itemName(d.item)} · ${d.series[metric].length} ${lang==='fa'?'سال':'years'} · ${lang==='fa'?'منبع':'source'}: FAOSTAT`,'success');$('exportFao').disabled=false}catch(e){clearSkeletons();lastFao=null;if(faoChart){faoChart.destroy();faoChart=null}$('faoTable').innerHTML='';$('faoMeta').textContent='FAOSTAT · QCL · Iran';status('faoStatus',`${lang==='fa'?'دریافت داده رسمی ناموفق بود؛ هیچ داده نمایشی جایگزین نشده است. ':'Official FAOSTAT retrieval failed; no demo data was substituted. '}${e.message}`,'error');$('exportFao').disabled=true}finally{$('loadFao').disabled=false}}function renderFao(d,metric){clearSkeletons();const rows=d.series[metric]||[],labels=rows.map(x=>x.year),values=rows.map(x=>x.value),units={production:'tonnes',area:'hectares',yield:'tonnes/hectare'};if(faoChart)faoChart.destroy();faoChart=new Chart($('faoChart'),{type:'line',data:{labels,datasets:[{label:`${itemName(d.item)} · ${metric}`,data:values,borderColor:'#18845b',backgroundColor:'rgba(24,132,91,.12)',fill:true,tension:.2,pointRadius:2}]},options:{responsive:true,maintainAspectRatio:false,plugins:{legend:{display:true}},scales:{y:{title:{display:true,text:units[metric]||''}}}}});$('faoTitle').textContent=`${itemName(d.item)} ${L('در ایران','in Iran')} · ${metric==='production'?L('تولید','Production'):metric==='area'?L('سطح برداشت','Harvested area'):L('عملکرد','Yield')}`;$('faoMeta').textContent=`FAOSTAT · QCL · Iran · ${d.source_url}`;$('faoTable').innerHTML=`<div class="analysis-card"><small>${L('تعداد سال‌های موجود','Years available')}</small><b>${rows.length}</b></div><div class="analysis-card"><small>${L('آخرین سال','Latest year')}</small><b>${rows.length?rows[rows.length-1].year:'—'}</b></div><div class="analysis-card"><small>${L('آخرین مقدار','Latest value')} (${units[metric]||''})</small><b>${rows.length?Number(rows[rows.length-1].value).toLocaleString(undefined,{maximumFractionDigits:2}):'—'}</b></div>`} $('loadFao').addEventListener('click',()=>loadFao(false));$('refreshFao').addEventListener('click',()=>loadFao(true));$('faoMetric').addEventListener('change',()=>{if(lastFao)renderFao(lastFao,$('faoMetric').value)});$('faoCrop').addEventListener('change',()=>loadFao(false));$('exportFao').addEventListener('click',()=>{if(!lastFao)return;const m=$('faoMetric').value,rows=lastFao.series[m]||[],csv='\ufeff'+[['year','value','unit'],...rows.map(x=>[x.year,x.value,x.unit||''])].map(r=>r.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=`FAOSTAT-Iran-${lastFao.item.key}-${m}.csv`;a.click();URL.revokeObjectURL(a.href)});
async function loadFaq(){const q=new URLSearchParams({lang,q:$('faqSearch')?.value||''});try{const r=await fetch(`/api/faq/?${q}`),d=await r.json();$('faqResults').innerHTML=d.items.map(x=>`<article class="faq-item"><div class="faq-cat">${esc(x.category)}</div><h4>${esc(x.question)}</h4><p>${esc(x.answer)}</p></article>`).join('')||`<p>${lang==='fa'?'موردی پیدا نشد.':'No matching questions.'}</p>`}catch(e){$('faqResults').textContent=e.message}}$('faqSearch').addEventListener('input',()=>loadFaq());
$('climUseMap').addEventListener('click',()=>{$('climLat').value=$('lat').value;$('climLon').value=$('lon').value});
$('runClimate').addEventListener('click',runClimate);
async function runClimate(){const btn=$('runClimate');btn.disabled=true;status('climStatus',lang==='fa'?'در حال محاسبه شاخص‌های اقلیمی…':'Computing climate indices…');$('climResult').innerHTML=skeletonCards(4);try{const y=Number($('climYears').value);const end=new Date(),start=new Date(end.getTime()-y*365*86400000);const fmt=d=>d.toISOString().slice(0,10).replaceAll('-','');const q=new URLSearchParams({lat:$('climLat').value,lon:$('climLon').value,start:fmt(start),end:fmt(end)});const r=await fetch(`/api/climate/?${q}`),d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);renderClimate(d);status('climStatus',lang==='fa'?'تحلیل اقلیمی کامل شد':'Climate analysis complete','success')}catch(e){$('climResult').innerHTML='';status('climStatus',e.message,'error')}finally{btn.disabled=false}}
function spiLabel(v){if(v==null)return'—';const a=Math.abs(v);if(a<1)return L('عادی','Normal');if(a<1.5)return L('خشک‌سال خفیف','Mild drought');if(a<2)return L('خشک‌سال متوسط','Moderate drought');return L('خشک‌سال شدید','Severe drought')}
let lastClimate=null,lastAdvice=null;
$('climPdf').addEventListener('click',()=>{const y=Number($('climYears').value);const end=new Date(),start=new Date(end.getTime()-y*365*86400000);const fmt=d=>d.toISOString().slice(0,10).replaceAll('-','');window.open(`/api/report/climate/?lat=${$('climLat').value}&lon=${$('climLon').value}&start=${fmt(start)}&end=${fmt(end)}`,'_blank')});
$('climCsv').addEventListener('click',()=>{if(!lastClimate){toast(L('ابتدا تحلیل اقلیمی را اجرا کنید','Run the climate analysis first'));return}const rows=[['month','tmean_c','tmax_c','tmin_c','precip_mm','pet_mm','water_balance_mm']];(lastClimate.monthly||[]).forEach(m=>rows.push([m.month,m.tmean_c??'',m.tmax_c??'',m.tmin_c??'',m.precip_mm,m.pet_mm,m.water_balance_mm]));const csv='\ufeff'+rows.map(r=>r.join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='climate-monthly.csv';a.click();URL.revokeObjectURL(a.href)});
function renderClimate(d){lastClimate=d;const ind=d.indicators||{};const pick=(k,label,unit)=>{const it=ind[k];if(!it)return null;let v=it.value;if(v&&typeof v==='object')v=JSON.stringify(v);return[v==null?'—':v+(unit?' '+unit:''),label,it]};const cards=[pick('temperature_anomaly_c',L('آنومالی دما','Temperature anomaly'),'°C'),pick('precipitation_anomaly_pct',L('آنومالی بارش','Precipitation anomaly'),'٪'),pick('spi_3m',L('SPI-3 ماهه','SPI-3 month'),''),pick('spi_6m',L('SPI-6 ماهه','SPI-6 month'),''),pick('spei_3m',L('SPEI-3 ماهه','SPEI-3 month'),''),pick('spei_6m',L('SPEI-6 ماهه','SPEI-6 month'),''),pick('heatwave',L('امواج گرما','Heatwave events'),''),pick('frost_days',L('روزهای یخبندان','Frost days'),L('روز','days')),pick('max_consecutive_dry_days',L('طولانی‌ترین خشکی','Longest dry spell'),L('روز','days')),pick('gdd_base10',L('GDD (پایه ۱۰°)','GDD (base 10°)'),'°C·day'),pick('water_balance',L('تراز آب دوره','Period water balance'),'mm')].filter(Boolean);let html=`<div class="panel" style="margin-top:16px"><div class="panel-title"><div><h3>${L('📊 شاخص‌های اقلیمی','📊 Climate indicators')} — ${d.location.lat.toFixed(3)} ، ${d.location.lon.toFixed(3)}</h3><p>${d.period.start} ${L('تا','to')} ${d.period.end} · ${d.period.months} ${L('ماه','months')} · ${L('منبع','Source')}: ${esc(d.source)} · ${L('دریافت','Retrieved')}: ${esc((d.fetched_at||'').slice(0,16).replace('T',' '))}</p></div></div><div class="stats-grid">${cards.map(c=>`<article class="stat"><span>${esc(c[1])}</span><b>${esc(String(c[0]))}</b><small>${esc(c[2].formula||'')}</small></article>`).join('')}</div></div>`;const spi6=ind.spi_6m?.series,spei6=ind.spei_6m?.series;if(spi6&&spei6&&spi6.length>3){const labels=(d.monthly||[]).map(m=>m.month).slice(-(spi6.length));if(climateChart)climateChart.destroy();climateChart=new Chart($('climateChart'),{type:'line',data:{labels,datasets:[{label:'SPI-6',data:spi6,borderColor:'#c45b5b',backgroundColor:'#c45b5b22',fill:true,tension:.2,pointRadius:0},{label:'SPEI-6',data:spei6,borderColor:'#087f8c',backgroundColor:'#087f8c22',fill:true,tension:.2,pointRadius:0}]},options:{responsive:true,maintainAspectRatio:false,scales:{y:{min:-3,max:3,ticks:{stepSize:1}}}}})}html+=`<div class="panel chart-panel"><div class="panel-title"><div><h3>${L('📈 SPI-6 و SPEI-6 (۶ ماهه)','📈 SPI-6 & SPEI-6 (6-month)')}</h3><p>${L('مقادیر مثبت = مرطوب، منفی = خشک | آستانه ±۱ عادی، ±۲ شدید','Positive = wet, negative = dry | threshold ±1 normal, ±2 severe')}</p></div></div><div class="chart-wrap"><canvas id="climateChart" role="img" aria-label="نمودار SPI و SPEI"></canvas></div></div>`;const recent=(d.monthly||[]).slice(-12);if(recent.length)html+=`<div class="panel"><div class="panel-title"><div><h3>${L('📅 ۱۲ ماه اخیر','📅 Last 12 months')}</h3><p>${L('تجمیع ماهانه از داده روزانه NASA POWER','Monthly aggregation of daily NASA POWER data')}</p></div></div><div class="analysis-grid">${recent.map(m=>`<div class="analysis-card"><small>${m.month}</small><b>${m.precip_mm} mm</b><span>${L('بارش','Precipitation')} · PET ${m.pet_mm} mm · ${L('تراز','Balance')} ${m.water_balance_mm>0?'+':''}${m.water_balance_mm} mm · T ${m.tmean_c??'—'}°C</span></div>`).join('')}</div></div>`;if(d.limitations?.length)html+=`<div class="notice"><b>${L('محدودیت‌های روش‌شناختی','Methodological limitations')}</b>${d.limitations.map(l=>`<p>• ${esc(l)}</p>`).join('')}<details style="margin-top:8px"><summary style="cursor:pointer;font-size:11px">${L('فرمول‌ها و منابع هر شاخص','Formulas and sources for each indicator')}</summary>${Object.entries(ind).map(([k,v])=>`<p style="font-size:10px;margin:4px 0"><b>${k}</b>: ${esc(v.formula||'')} — ${esc(v.source||'')} — ${esc(v.reference_period||'')}</p>`).join('')}</details></div>`;$('climResult').innerHTML=html}
const SAT_LAYERS={truecolor:{layer:'MODIS_Terra_CorrectedReflectance_TrueColor',desc_fa:'تصویر واقعی رنگی Terra — مشاهده بصری، نه اندازه‌گیری کمی',desc_en:'True-color Terra imagery — visual context, not quantitative measurement',tms:'GoogleMapsCompatible_Level9',ext:'png',maxZoom:9,defaultDays:2},ndvi:{layer:'MODIS_Terra_NDVI_8Day',desc_fa:'شاخص NDVI — سلامت و پوشش گیاه از MODIS Terra',desc_en:'NDVI index — vegetation health and cover from MODIS Terra',tms:'GoogleMapsCompatible_Level9',ext:'png',maxZoom:9,defaultDays:10},evi:{layer:'MODIS_Terra_EVI_8Day',desc_fa:'شاخص EVI — حساس‌تر به پوشش متراکم از NDVI',desc_en:'EVI index — more sensitive to dense vegetation than NDVI',tms:'GoogleMapsCompatible_Level9',ext:'png',maxZoom:9,defaultDays:10},lst:{layer:'MODIS_Terra_L3_Land_Surface_Temp_Daily_Day',desc_fa:'دمای سطح زمین روزانه — MODIS Terra',desc_en:'Daily land surface temperature — MODIS Terra',tms:'GoogleMapsCompatible_Level7',ext:'png',maxZoom:7,defaultDays:2},lst_night:{layer:'MODIS_Aqua_L3_Land_Surface_Temp_Daily_Night',desc_fa:'دمای سطح زمین شبانه — MODIS Aqua',desc_en:'Night-time land surface temperature — MODIS Aqua',tms:'GoogleMapsCompatible_Level7',ext:'png',maxZoom:7,defaultDays:2},ndvi_monthly:{layer:'MODIS_Terra_L3_NDVI_Monthly',desc_fa:'NDVI ماهانه — روند فصلی پوشش گیاهی',desc_en:'Monthly NDVI — seasonal vegetation trend',tms:'GoogleMapsCompatible_Level7',ext:'png',maxZoom:7,defaultDays:40},evi16:{layer:'MODIS_Aqua_L3_EVI_16Day',desc_fa:'EVI ۱۶ روزه — MODIS Aqua',desc_en:'16-day EVI — MODIS Aqua',tms:'GoogleMapsCompatible_Level9',ext:'png',maxZoom:9,defaultDays:10},smap:{layer:'SMAP_L3_Passive_Day_Soil_Moisture',desc_fa:'رطوبت خاک — ماهواره SMAP (پاسیو مایکروویو)',desc_en:'Soil moisture — SMAP passive microwave',tms:'GoogleMapsCompatible_Level6',ext:'png',maxZoom:6,defaultDays:5}};
