let faoRankChart=null,faoCompareChart=null,lastFaoWorld=null;
$('loadFaoWorld').addEventListener('click',loadFaoWorld);$('faoWorldMetric').addEventListener('change',()=>{if(lastFaoWorld)loadFaoWorld()});
async function loadFaoWorld(){const crop=$('faoCrop').value,metric=$('faoWorldMetric').value;status('faoWorldStatus',lang==='fa'?'در حال دریافت رتبه‌بندی جهانی از FAOSTAT…':'Fetching world ranking from FAOSTAT…');$('loadFaoWorld').disabled=true;$('faoWorldResult').innerHTML=skeletonCards(3);try{const r=await fetch(`/api/fao/world/${encodeURIComponent(crop)}/?element=${metric}&top=12`),d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);lastFaoWorld=d;renderFaoWorld(d);status('faoWorldStatus',lang==='fa'?`رتبه‌بندی ${d.ranking.length} کشور دریافت شد`:`Ranking for ${d.ranking.length} countries received`,'success')}catch(e){$('faoWorldResult').innerHTML='';status('faoWorldStatus',e.message,'error')}finally{$('loadFaoWorld').disabled=false}}
function renderFaoWorld(d){const unit=d.ranking[0]?.unit||'';const top=d.ranking.slice(0,12);let html=`<div class="panel" style="margin-top:14px"><div class="panel-title"><div><h3>${L('🏆 رتبه‌بندی','🏆 Ranking')} ${esc(itemName(d.item))} — ${esc(d.element)}</h3><p>${L('سال مرجع','Reference year')}: ${top[0]?.year} · ${L('واحد','Unit')}: ${esc(unit)} · ${L('منبع','Source')}: FAOSTAT QCL (${L('همه مناطق','all areas')})</p></div>${d.iran?`<div class="stat" style="min-width:160px"><span>${L('رتبه ایران',"Iran's rank")}</span><b>#${d.iran.rank??'—'}</b><small>${d.iran.value?.toLocaleString('en-US')} ${esc(unit)}</small></div>`:''}</div><div class="chart-wrap" style="height:280px"><canvas id="faoRankChart"></canvas></div><div class="analysis-grid" style="margin-top:12px">${top.map(r=>`<div class="analysis-card" ${r.is_iran?'style="border-color:#087f8c"':''}><small>#${r.rank} ${esc(r.area||'')}</small><b>${r.value.toLocaleString('en-US')} ${esc(r.unit)}</b><span>${r.year}</span></div>`).join('')}</div></div>`;const cmp=d.comparison||{};const keys=Object.keys(cmp);if(keys.length>1){const years=[...new Set(keys.flatMap(k=>cmp[k].points.map(p=>p.year)))].sort();const palette=['#087f8c','#c45b5b','#e7a33e','#6c8d54','#8256a1','#4263a5'];html+=`<div class="panel chart-panel" style="margin-top:14px"><div class="panel-title"><div><h3>${L('📈 مقایسه روند','📈 Trend comparison')} ${esc(itemName(d.item))}</h3><p>${L('ایران در برابر بزرگ‌ترین تولیدکنندگان — داده واقعی FAOSTAT','Iran vs the largest producers — real FAOSTAT data')}</p></div></div><div class="chart-wrap"><canvas id="faoCompareChart"></canvas></div></div>`}$('faoWorldResult').innerHTML=html;if(faoRankChart)faoRankChart.destroy();const rc=$('faoRankChart');if(rc){faoRankChart=new Chart(rc,{type:'bar',data:{labels:top.map(r=>r.area),datasets:[{data:top.map(r=>r.value),backgroundColor:top.map(r=>r.is_iran?'#087f8c':'#4263a5'),borderRadius:6}]},options:{indexAxis:'y',responsive:true,maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{x:{ticks:{callback:v=>v>=1e6?(v/1e6).toFixed(1)+'M':v>=1e3?(v/1e3).toFixed(0)+'K':v}}}}})}if(keys.length>1&&$('faoCompareChart')){if(faoCompareChart)faoCompareChart.destroy();faoCompareChart=new Chart($('faoCompareChart'),{type:'line',data:{labels:years,datasets:keys.map((k,i)=>({label:cmp[k].area,data:years.map(y=>{const p=cmp[k].points.find(x=>x.year===y);return p?p.value:null}),borderColor:palette[i%palette.length],backgroundColor:palette[i%palette.length]+'22',fill:false,tension:.2,pointRadius:0,borderWidth:2}))},options:{responsive:true,maintainAspectRatio:false}})}}
async function askAgent(q){if(!q)return;status('agentStatus',lang==='fa'?'در حال تحلیل سؤال…':'Analyzing question…');$('askAgent').disabled=true;$('agentResult').innerHTML=skeletonCards(2);try{const r=await fetch(`/api/agent/?q=${encodeURIComponent(q)}`),d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);renderAgent(d,q);status('agentStatus',lang==='fa'?'پاسخ آماده شد':'Answer ready','success')}catch(e){$('agentResult').innerHTML='';status('agentStatus',e.message,'error')}finally{$('askAgent').disabled=false}}
$('askAgent').addEventListener('click',()=>askAgent($('agentQ').value.trim()));$('agentQ').addEventListener('keydown',e=>{if(e.key==='Enter')askAgent($('agentQ').value.trim())});document.querySelectorAll('.agent-ex').forEach(b=>b.addEventListener('click',()=>{$('agentQ').value=b.textContent;askAgent(b.textContent)}));
function renderAgent(d,q){const intentFa={drought:L('خشکسالی','Drought'),temperature:L('دما و اقلیم','Temperature & climate'),weather:L('وضعیت هوا','Weather status'),crop_advice:L('مشاوره محصول','Crop advice'),vegetation:L('پوشش گیاهی','Vegetation'),production:L('تولید و عملکرد','Production & yield'),unknown:L('نامشخص','Unknown')}[d.intent]||d.intent;let html=`<div class="panel" style="margin-top:14px"><div class="panel-title"><div><h3>💬 ${esc(q)}</h3><p>${L('قصد','Intent')}: ${esc(intentFa)} · ${L('اطمینان','Confidence')}: ${Math.round((d.confidence||0)*100)}٪ ${d.place?`· ${L('مکان','Location')}: ${esc(d.place.split(',').slice(0,2).join('، '))}`:''}</p></div></div><p style="font-size:15px;line-height:1.9">${esc(d.answer_fa||'')}</p>`;if(d.data){const entries=Object.entries(d.data).filter(([k,v])=>v!=null&&!Array.isArray(v)&&typeof v!=='object');if(entries.length)html+=`<div class="stats-grid" style="margin-top:12px">${entries.slice(0,6).map(([k,v])=>`<article class="stat"><span>${esc(k)}</span><b>${esc(String(v))}</b></article>`).join('')}</div>`}if(d.data_sources?.length)html+=`<p style="margin-top:10px;font-size:12px;color:var(--muted)">📡 ${L('منابع','Sources')}: ${d.data_sources.map(esc).join(' · ')}</p>`;if(d.limitations?.length)html+=`<div class="notice" style="margin-top:10px"><b>${L('محدودیت‌ها','Limitations')}</b>${d.limitations.map(l=>`<p style="font-size:12px">• ${esc(l)}</p>`).join('')}</div>`;html+='</div>';$('agentResult').innerHTML=html}
