async function initParamChecks(){try{const r=await fetch('/api/power/parameters/'),d=await r.json();const box=document.querySelector('.checks');if(!box)return;const existing=new Set([...box.querySelectorAll('input')].map(i=>i.value));d.parameters.forEach(p=>{if(!existing.has(p.code)){const l=document.createElement('label');l.innerHTML=`<input type="checkbox" value="${esc(p.code)}"> ${esc(p.code)}`;box.append(l)}})}catch(e){}}
function setupRangePresets(){const box=$('rangePresets');if(!box)return;const fmt=d=>d.toISOString().slice(0,10);box.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{const end=new Date(),start=new Date(end.getTime()-Number(b.dataset.days)*86400000);$('end').value=fmt(end);$('start').value=fmt(start)}))}
function setupPresets(){const box=document.querySelector('.checks');if(!box)return;const wrap=document.createElement('div');wrap.className='quick-searches';wrap.style.marginTop='8px';wrap.innerHTML=`<button class="btn btn-ghost" data-p="ag" data-i18n="preset_ag">${L('پیش‌تنظیم کشاورزی','Agriculture preset')}</button><button class="btn btn-ghost" data-p="energy" data-i18n="preset_energy">${L('انرژی خورشیدی','Solar energy')}</button><button class="btn btn-ghost" data-p="all" data-i18n="preset_all">${L('همه پارامترها','All parameters')}</button>`;box.insertAdjacentElement('afterend',wrap);applyLanguage();const sets={ag:['T2M','PRECTOTCORR','RH2M','ALLSKY_SFC_SW_DWN','EVPTRNS'],energy:['ALLSKY_SFC_SW_DWN','T2M','RH2M','WS10M'],all:null};wrap.querySelectorAll('button').forEach(b=>b.addEventListener('click',()=>{const s=sets[b.dataset.p];box.querySelectorAll('input').forEach(i=>{i.checked=s===null||s.includes(i.value)})}))}
function setupModisDate(){const row=document.querySelector('.coord-row');if(!row||!modisLayer)return;const l=document.createElement('label');l.innerHTML='🛰 <input type="date" id="modisDate">';row.append(l);const inp=l.querySelector('input'),fmt=d=>d.toISOString().slice(0,10);inp.value=fmt(new Date(Date.now()-2*86400000));inp.max=fmt(new Date());inp.addEventListener('change',()=>{const d=inp.value||fmt(new Date(Date.now()-2*86400000));modisLayer.setUrl(`https://gibs.earthdata.nasa.gov/wmts/epsg3857/best/MODIS_Terra_CorrectedReflectance_TrueColor/default/${d}/GoogleMapsCompatible_Level9/{z}/{y}/{x}.jpg`)})}
