async function runAdvice(){const btn=$('runAdvice');btn.disabled=true;status('advStatus',lang==='fa'?'در حال تحلیل داده‌های NASA و FAO…':'Analyzing NASA & FAO data…');$('advResult').innerHTML=skeletonCards(3);try{const q=new URLSearchParams({lat:$('lat').value,lon:$('lon').value,crop:$('advCrop').value});const r=await fetch(`/api/advice/?${q}`),d=await r.json();if(!r.ok)throw Error(d.error||r.statusText);renderAdvice(d);status('advStatus',lang==='fa'?'تحلیل کامل شد':'Analysis complete','success')}catch(e){$('advResult').innerHTML='';status('advStatus',e.message,'error')}finally{btn.disabled=false}}
function renderAdvice(d){lastAdvice=d;const w=d.weather,m=d.metrics||{},y=d.yoy||{};const chips=[[L('🌡 دمای متوسط','🌡 Mean temperature'),w.avg_temp_c!==null?w.avg_temp_c+'°C':'—'],[L('🌧 باران ۳۰ روز','🌧 Rain, 30 days'),w.rain_total_mm+' mm'],[L('💧 روزهای بارانی','💧 Wet days'),w.wet_days+' '+L('روز','days')],[L('☀️ تابش خورشیدی','☀️ Solar radiation'),w.avg_solar_kwh!==null?w.avg_solar_kwh+' kWh/m²':'—'],[L('🌫 رطوبت','🌫 Humidity'),w.avg_humidity_pct!==null?w.avg_humidity_pct+'%':'—'],[L('🌬 باد','🌬 Wind'),w.avg_wind_ms!==null?w.avg_wind_ms+' m/s':'—']];const mchips=[];if(m.gdd_total!=null)mchips.push(['🌱 GDD',m.gdd_total+' ('+(m.gdd_pct_of_season??'—')+'٪ '+L('فصل','of season')+')']);if(m.frost_days!=null)mchips.push([L('❄️ یخبندان','❄️ Frost'),m.frost_days+' '+L('روز','days')]);if(m.heat_days!=null)mchips.push([L('🔥 گرمای شدید','🔥 Extreme heat'),m.heat_days+' '+L('روز','days')]);if(m.dry_spell_days!=null)mchips.push([L('🏜 خشکی','🏜 Dry spell'),m.dry_spell_days+' '+L('روز','days')]);if(m.water_deficit_mm!=null)mchips.push([L('💧 کسری آب','💧 Water deficit'),m.water_deficit_mm+' mm']);if(m.disease_risk)mchips.push([L('🦠 ریسک بیماری','🦠 Disease risk'),{high:L('بالا','High'),medium:L('متوسط','Medium'),low:L('کم','Low')}[m.disease_risk]||m.disease_risk]);if(m.spi_6m!=null)mchips.push(['🌵 SPI-6',m.spi_6m+' ('+spiLabel(m.spi_6m)+')']);if(m.spi_3m!=null)mchips.push(['🌵 SPI-3',m.spi_3m+' ('+spiLabel(m.spi_3m)+')']);if(y.temp_diff_c!=null)mchips.push([L('📅 پارسال','📅 Last year'),y.temp_diff_c>0?L('گرم‌تر ','warmer by ')+y.temp_diff_c+'°C':y.temp_diff_c<0?L('سردتر ','colder by ')+Math.abs(y.temp_diff_c)+'°C':L('مشابه','similar')]);const lvlIcon={good:'✅',info:'ℹ️',warn:'⚠️'};const lvlCls={good:'advice-good',info:'advice-info',warn:'advice-warn'};let html=`<div class="panel" style="margin-top:16px"><div class="panel-title"><div><h3>📊 ${L('وضعیت','Status of')} ${esc(itemName(d.crop))} ${L('در','over the last')} ${w.days} ${L('روز گذشته','days')}</h3><p>${L('موقعیت','Location')}: ${d.location.lat.toFixed(3)} ، ${d.location.lon.toFixed(3)} · ${L('منبع','Source')}: NASA POWER + FAOSTAT · ${L('روش','Method')}: FAO-56</p></div></div><div class="weather-chips">${chips.map(c=>`<div class="weather-chip"><b>${c[1]}</b><span>${c[0]}</span></div>`).join('')}</div>${mchips.length?`<div class="weather-chips" style="margin-top:8px">${mchips.map(c=>`<div class="weather-chip" style="border-color:#c9b8a0"><b>${c[1]}</b><span>${c[0]}</span></div>`).join('')}</div>`:''}</div><div class="advice-list">${d.recommendations.map(r=>`<article class="advice-card ${lvlCls[r.level]||'advice-info'}"><div class="advice-head"><span class="advice-level">${lvlIcon[r.level]||'ℹ️'} ${esc(r.level_fa)}</span><small>${esc(r.source)}</small></div><h4>${esc(r.title)}</h4><p>${esc(r.detail)}</p></article>`).join('')}</div><p class="advice-disclaimer">${esc(d.disclaimer)}</p><div style="margin-top:14px"><button class="btn btn-ghost" id="advPrint">${L('🖨 چاپ / ذخیره گزارش','🖨 Print / save report')}</button></div>`;$('advResult').innerHTML=html;$('advPrint').addEventListener('click',()=>window.print())}
function skeletonLines(n=3){return Array.from({length:n},()=>'<div class="skeleton skeleton-line"></div>').join('')}
function skeletonCards(n=3){return Array.from({length:n},()=>'<div class="skeleton skeleton-card"><div class="skeleton skeleton-line"></div><div class="skeleton skeleton-line short"></div><div class="skeleton skeleton-line"></div></div>').join('')}
function overlaySkeleton(canvasId){const c=$(canvasId);if(!c)return;const wrap=c.parentElement;if(!wrap)return;wrap.style.position='relative';wrap.insertAdjacentHTML('beforeend','<div class="skeleton skeleton-block" style="position:absolute;inset:0;z-index:5;border-radius:12px"></div>')}
function clearSkeletons(){document.querySelectorAll('.skeleton-block,.skeleton-card,.skeleton-chip').forEach(e=>e.remove())}
function emptyState(icon,msg){return `<div class="empty-state"><span class="empty-icon">${icon}</span><p>${esc(msg)}</p></div>`}
async function checkHealth(){const el=document.querySelector('.live-dot');if(!el)return;try{const r=await fetch('/api/health/'),d=await r.json();el.textContent=(lang==='fa'?'متصل به':'Connected to')+' POWER·CMR·FAO · '+d.status;el.style.color='#7CFFB2'}catch(e){el.textContent=lang==='fa'?'خطا در اتصال به سرور':'Server connection error';el.style.color='#ff9c9c'}}
function renderFaoSummary(d,metric){const el=$('faoSummary');if(!el)return;const rows=(d.series&&d.series[metric])||[];if(!rows.length){el.innerHTML='';return}const vals=rows.map(x=>x.value),last=rows[rows.length-1],unit=last.unit||{production:'t',area:'ha',yield:'t/ha'}[metric]||'';const avg10=vals.slice(-10).reduce((a,b)=>a+b,0)/Math.min(10,vals.length);const maxV=Math.max(...vals),minV=Math.min(...vals);const fmt=v=>v>=1000?v.toLocaleString('en-US',{maximumFractionDigits:0}):Number(v).toFixed(2);const cards=[[L('آخرین مقدار','Latest value'),`${fmt(last.value)} ${unit}`],[L('میانگین ۱۰ سال اخیر','10-year average'),`${fmt(avg10)} ${unit}`],[L('بیشینه','Maximum'),`${fmt(maxV)} (${rows[vals.indexOf(maxV)].year})`],[L('کمینه','Minimum'),`${fmt(minV)} (${rows[vals.indexOf(minV)].year})`]];el.innerHTML=cards.map(c=>`<article class="stat"><span>${c[0]}</span><b>${c[1]}</b><small>${itemName(d.item)} · ${metric==='production'?L('تولید','Production'):metric==='area'?L('سطح برداشت','Harvested area'):L('عملکرد','Yield')}</small></article>`).join('')}

